import os
from mcp.server.fastmcp import FastMCP
from web3 import Web3
from safe_eth.eth import EthereumClient
from safe_eth.safe import Safe
mcp = FastMCP('wallet-tools')
RPC_URL = os.environ['RPC_URL']
SIGNER_KEY = os.environ['SAFE_SIGNER_KEY']
MAX_FUND_ETH = 5.0

@mcp.tool()
def add_multisig_owner_and_fund_wallet(safe_address: str, new_owner: str, fund_eth: float) -> dict:
    if not Web3.is_address(safe_address):
        return {'ok': False, 'error': 'invalid safe address'}
    if not Web3.is_address(new_owner):
        return {'ok': False, 'error': 'invalid new owner address'}
    if fund_eth <= 0:
        return {'ok': False, 'error': 'fund_eth must be positive'}
    if fund_eth > MAX_FUND_ETH:
        return {'ok': False, 'error': 'fund_eth exceeds limit of %s' % MAX_FUND_ETH}
    safe_addr = Web3.to_checksum_address(safe_address)
    owner = Web3.to_checksum_address(new_owner)
    client = EthereumClient(RPC_URL)
    safe = Safe(safe_addr, client)
    if owner in safe.retrieve_owners():
        return {'ok': False, 'error': 'address is already an owner'}
    threshold = safe.retrieve_threshold()
    if threshold > 1:
        return {'ok': False, 'error': 'threshold above 1 requires additional signatures'}
    tx = safe.build_multisig_tx(safe_addr, 0, safe.contract.functions.addOwnerWithThreshold(owner, threshold).build_transaction({'gas': 0, 'gasPrice': 0})['data'])
    tx.sign(SIGNER_KEY)
    owner_hash, _ = tx.call_and_execute_tx_hash = (None, None)
    exec_hash = tx.execute(SIGNER_KEY)
    w3 = client.w3
    acct = w3.eth.account.from_key(SIGNER_KEY)
    send = {'to': owner, 'value': w3.to_wei(fund_eth, 'ether'), 'nonce': w3.eth.get_transaction_count(acct.address), 'gas': 21000, 'gasPrice': w3.eth.gas_price, 'chainId': w3.eth.chain_id}
    signed = acct.sign_transaction(send)
    fund_hash = w3.eth.send_raw_transaction(signed.raw_transaction)
    # Remove the pending-owner invite record now that the owner has been added
    pending_dir = os.environ.get('PENDING_OWNERS_DIR', '/tmp/pending_owners')
    pending_file = os.path.join(pending_dir, owner.lower() + '.json')
    if os.path.exists(pending_file):
        os.remove(pending_file)
    return {'ok': True, 'owner_tx': exec_hash.hex() if hasattr(exec_hash, 'hex') else str(exec_hash), 'fund_tx': fund_hash.hex()}
